// Generated from DataV China province boundary GeoJSON with a shared Web Mercator projection.
// Keep this file data-only so the coverage map stays fast and deterministic.

export const CHINA_MAP_VIEWBOX = "0 0 100 88";

const LNG_MIN = 73;
const LNG_MAX = 135.5;
const LAT_MIN = 17.5;
const LAT_MAX = 54;
const PAD = 4;
const WIDTH = 100;
const HEIGHT = 88;

function mercatorY(lat: number) {
  const rad = lat * Math.PI / 180;
  return Math.log(Math.tan(Math.PI / 4 + rad / 2));
}

export function projectChinaPoint(lng: number, lat: number) {
  const yMin = mercatorY(LAT_MIN);
  const yMax = mercatorY(LAT_MAX);
  return {
    x: PAD + ((lng - LNG_MIN) / (LNG_MAX - LNG_MIN)) * (WIDTH - PAD * 2),
    y: PAD + ((yMax - mercatorY(lat)) / (yMax - yMin)) * (HEIGHT - PAD * 2),
  };
}

